<script setup lang="ts">const{profile,pending,error,loadProfile,saveProfile}=useAccount();const form=reactive({displayName:"",bio:"",avatarKey:""}),saved=ref(false);useHead({title:"پروفایل من — هفت‌سو",meta:[{name:"robots",content:"noindex,nofollow"}]});onMounted(async()=>{const value=await loadProfile();if(value){form.displayName=value.display_name;form.bio=value.bio;form.avatarKey=value.avatar_key??""}});async function submit(){await saveProfile(form);saved.value=true;setTimeout(()=>saved.value=false,2500);}</script>
<template><AccountShell title="پروفایل و اطلاعات حساب" description="اطلاعاتی را که سایر کاربران درباره شما می‌بینند مدیریت کنید."><form class="account-form" @submit.prevent="submit"><label>نام نمایشی<input v-model="form.displayName" minlength="2" maxlength="80" required autocomplete="name"></label><label>درباره من<textarea v-model="form.bio" maxlength="300" rows="4"/></label><label>شناسه تصویر پروفایل<input v-model="form.avatarKey" maxlength="160" placeholder="پس از بارگذاری تصویر تکمیل می‌شود"></label><p v-if="error" class="inline-error" role="alert">{{error}}</p><p v-if="saved" class="inline-success" role="status">پروفایل ذخیره شد.</p><button class="button button-primary" type="submit" :disabled="pending">ذخیره تغییرات</button></form><section id="identity" class="account-section"><h2>وضعیت تأیید هویت</h2><IdentityStatusCard :status="profile?.identity_status??'unverified'"/></section></AccountShell></template>
